5	namespace Doctrine\Persistence\Mapping\Driver;
6	
7	use AppendIterator;
8	use CallbackFilterIterator;
9	use Doctrine\Persistence\Mapping\MappingException;
10	use FilesystemIterator;
11	use InvalidArgumentException;
12	use Iterator;
13	use RecursiveDirectoryIterator;
14	use RecursiveIteratorIterator;
15	use ReflectionClass;
16	use RegexIterator;
17	use SplFileInfo;
18	
19	use function array_key_exists;
20	use function array_map;
21	use function assert;
22	use function get_debug_type;
23	use function get_declared_classes;
24	use function is_dir;
25	use function preg_quote;
26	use function realpath;
27	use function sprintf;
28	use function str_replace;
29	use function str_starts_with;
30	
31	/**
32	 * ClassLocator implementation that uses a list of file names to locate PHP files
33	 * and extract class names from them.
34	 *
35	 * It is compatible with the Symfony Finder component, but does not require it.
36	 */
37	final class FileClassLocator implements ClassLocator
38	{
39	    /** @param iterable<SplFileInfo> $files An iterable of files to include. */
40	    public function __construct(
41	        private iterable $files,
42	    ) {
43	    }
44	
45	    /** @return list<class-string> */
46	    public function getClassNames(): array
47	    {
48	        $includedFiles = [];
49	
50	        foreach ($this->files as $file) {
51	            // @phpstan-ignore function.alreadyNarrowedType, instanceof.alwaysTrue
52	            assert($file instanceof SplFileInfo, new InvalidArgumentException(sprintf('Expected an iterable of SplFileInfo, got %s', get_debug_type($file))));
53	
54	            // Skip non-files
55	            if (! $file->isFile()) {
56	                continue;
57	            }
58	
59	            // getRealPath() returns false if the file is in a phar archive
60	            // @phpstan-ignore ternary.shortNotAllowed (false is the only falsy value getRealPath() may return)
61	            $fileName = $file->getRealPath() ?: $file->getPathname();
62	
63	            $includedFiles[$fileName] = true;
64	            require_once $fileName;
65	        }
66	
67	        $classes = [];
68	        foreach (get_declared_classes() as $className) {
69	            $fileName = (new ReflectionClass($className))->getFileName();
70	
71	            if ($fileName === false || ! array_key_exists($fileName, $includedFiles)) {
72	                continue;
73	            }
74	
75	            $classes[] = $className;
76	        }
77	
78	        return $classes;
79	    }
80	
81	    /**
82	     * Creates a FileClassLocator from an array of directories.
83	     *
84	     * @param list<string> $directories
85	     * @param list<string> $excludedDirectories Directories to exclude from the search.
86	     * @param string       $fileExtension       The file extension to look for (default is '.php').
87	     *
88	     * @throws MappingException if any of the directories are not valid.
89	     */
90	    public static function createFromDirectories(
91	        array $directories,
92	        array $excludedDirectories = [],
93	        string $fileExtension = '.php',
94	    ): self {
95	        $filesIterator = new AppendIterator();
96	
97	        foreach ($directories as $directory) {
98	            if (! is_dir($directory)) {
99	                throw MappingException::fileMappingDriversRequireConfiguredDirectoryPath($directory);
100	            }
101	
102	            /** @var Iterator<array-key,SplFileInfo> $iterator */
103	            $iterator = new RegexIterator(
104	                new RecursiveIteratorIterator(
105	                    new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS),
106	                    RecursiveIteratorIterator::LEAVES_ONLY,
107	                ),
108	                sprintf('/%s$/', preg_quote($fileExtension, '/')),
109	                RegexIterator::MATCH,
110	            );
111	
112	            $filesIterator->append($iterator);
113	        }
114	
115	        if ($excludedDirectories !== []) {
116	            $excludedDirectories = array_map(
117	                // realpath() returns false if the file is in a phar archive
118	                // @phpstan-ignore ternary.shortNotAllowed (false is the only falsy value realpath() may return)
119	                static fn (string $dir): string => str_replace('\\', '/', realpath($dir) ?: $dir),
120	                $excludedDirectories,
121	            );
122	
123	            $filesIterator = new CallbackFilterIterator(
124	                $filesIterator,
125	                static function (SplFileInfo $file) use ($excludedDirectories): bool {
126	                    // getRealPath() returns false if the file is in a phar archive
127	                    // @phpstan-ignore ternary.shortNotAllowed (false is the only falsy value getRealPath() may return)
128	                    $sourceFile = str_replace('\\', '/', $file->getRealPath() ?: $file->getPathname());
129	
130	                    foreach ($excludedDirectories as $excludedDirectory) {
131	                        if (str_starts_with($sourceFile, $excludedDirectory)) {
132	                            return false;
133	                        }
134	                    }
135	
136	                    return true;
137	                },
138	            );
139	        }
140	
141	        return new self($filesIterator);
142	    }
